-- Create cleaned_measurements table using subqueries
CREATE TABLE cleaned_measurements AS
SELECT m.* 
FROM measurements m
WHERE m.status = 'valid'
AND m.reaction_ms >= (
    SELECT (SELECT AVG(reaction_ms) FROM measurements) - 3.0 * (
        SELECT ((SELECT AVG(reaction_ms * reaction_ms) FROM measurements) - 
            ((SELECT AVG(reaction_ms) FROM measurements) * (SELECT AVG(reaction_ms) FROM measurements)))
    )
)
AND m.reaction_ms <= (
    SELECT (SELECT AVG(reaction_ms) FROM measurements) + 3.0 * (
        SELECT ((SELECT AVG(reaction_ms * reaction_ms) FROM measurements) - 
            ((SELECT AVG(reaction_ms) FROM measurements) * (SELECT AVG(reaction_ms) FROM measurements)))
    )
)
AND m.cognitive_score >= (
    SELECT (SELECT AVG(cognitive_score) FROM measurements) - 3.0 * (
        SELECT ((SELECT AVG(cognitive_score * cognitive_score) FROM measurements) - 
            ((SELECT AVG(cognitive_score) FROM measurements) * (SELECT AVG(cognitive_score) FROM measurements)))
    )
)
AND m.cognitive_score <= (
    SELECT (SELECT AVG(cognitive_score) FROM measurements) + 3.0 * (
        SELECT ((SELECT AVG(cognitive_score * cognitive_score) FROM measurements) - 
            ((SELECT AVG(cognitive_score) FROM measurements) * (SELECT AVG(cognitive_score) FROM measurements)))
    )
);

-- Verify which records were excluded
SELECT m.session_id, m.participant_id, m.condition, m.cognitive_score, m.reaction_ms, m.status
FROM measurements m
WHERE m.status != 'valid'
   OR m.reaction_ms < (
        SELECT (SELECT AVG(reaction_ms) FROM measurements) - 3.0 * (
            SELECT ((SELECT AVG(reaction_ms * reaction_ms) FROM measurements) - 
                ((SELECT AVG(reaction_ms) FROM measurements) * (SELECT AVG(reaction_ms) FROM measurements)))
        )
    )
   OR m.reaction_ms > (
        SELECT (SELECT AVG(reaction_ms) FROM measurements) + 3.0 * (
            SELECT ((SELECT AVG(reaction_ms * reaction_ms) FROM measurements) - 
                ((SELECT AVG(reaction_ms) FROM measurements) * (SELECT AVG(reaction_ms) FROM measurements)))
        )
    )
   OR m.cognitive_score < (
        SELECT (SELECT AVG(cognitive_score) FROM measurements) - 3.0 * (
            SELECT ((SELECT AVG(cognitive_score * cognitive_score) FROM measurements) - 
                ((SELECT AVG(cognitive_score) FROM measurements) * (SELECT AVG(cognitive_score) FROM measurements)))
        )
    )
   OR m.cognitive_score > (
        SELECT (SELECT AVG(cognitive_score) FROM measurements) + 3.0 * (
            SELECT ((SELECT AVG(cognitive_score * cognitive_score) FROM measurements) - 
                ((SELECT AVG(cognitive_score) FROM measurements) * (SELECT AVG(cognitive_score) FROM measurements)))
        )
    )
ORDER BY m.reaction_ms DESC;
